// Allocation function example
function allocateBudget(tenants, totalUnits){
  const base=1; // base per-tenant
  const sumCKNE=tenants.reduce((a,t)=>a+t.ckne,0);
  const alloc={};
  tenants.forEach(t=>{ alloc[t.id]= base + (t.ckne/sumCKNE)*(totalUnits - tenants.length*base);});
