## Code Example

```javascript
// Token bucket outline
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate;
    this.last = Date.now();
  }
  allow(n = 1) {
    this.refill();
    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }
  refill() {
    const now = Date.now();
    const dt = (now - this.last) / 1000;
    if (dt > 0) {
      this.tokens = Math.min(this.capacity, this.tokens + dt * this.refillRate);
      this.last = now;
    }
  }
}
```

